// PromptReply: a short UI promo, timed to a measured 5 s reference. A chat prompt types itself into a rounded
// box and sends; the shot cuts to the agent's reply, which builds up on a scrolling page: two activity rows, a status
// line, a serif reply, a brand chip, a small table and the action icons. Dark grey UI, a warm tint on fresh type.
//
// Timing is the reference's, measured frame by frame at 60 fps. The reference (not committed) goes in
// reference/reel.mp4. Everything you see is a prop (text, colours, fonts); see README.md.
//
// Render from the kinetograph-ui root:
//   node ../kinetograph/packages/cli/dist/cli.js strip templates/prompt-reply/index.tsx -n 12 -o templates/prompt-reply/out/strip.png
//   node ../kinetograph/packages/cli/dist/cli.js render templates/prompt-reply/index.tsx -o templates/prompt-reply/out/prompt-reply.mp4

import React from 'react';
import { Composition, Layer, Rect, registerRoot, useCurrentFrame } from '@kinetographdev/core';
import { CUT, DURATION, FPS, HEIGHT, STAGE_SCALE, WIDTH, defaultProps, loadFaces } from './scenes/lib.js';
import type { PromptReplyProps } from './scenes/lib.js';
import { PromptShot } from './scenes/prompt.js';
import { ReplyShot } from './scenes/reply.js';

export const PromptReply: React.FC<PromptReplyProps> = (props) => {
  const f = useCurrentFrame();
  const faces = loadFaces(props.fonts);
  return (
    <Layer id="stage">
      <Rect id="page" width={WIDTH} height={HEIGHT} fill={props.colors.background} />
      <Layer id="ref-pixels" scale={STAGE_SCALE}>
        {f < CUT ? <PromptShot f={f} props={props} faces={faces} /> : <ReplyShot f={f} props={props} faces={faces} />}
      </Layer>
    </Layer>
  );
};

registerRoot(() => (
  <Composition
    id="PromptReply"
    component={PromptReply}
    durationInFrames={DURATION}
    fps={FPS}
    width={WIDTH}
    height={HEIGHT}
    defaultProps={defaultProps}
  />
));

// Shared bits of the prompt-reply component: size, timing helpers, fonts, colours, the line icons.
// All drawing is authored in the reference's own pixels (960x540); the stage scales it by STAGE_SCALE.

import React from 'react';
import { Easing, Layer, Path, interpolate, interpolateColors } from '@kinetographdev/core';
import type { Stroke } from '@kinetographdev/core';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';

export const FPS = 60;
export const DURATION = 300; // 5.0 s
export const WIDTH = 1920;
export const HEIGHT = 1080;
/** The reference is 960x540; every number below is in its pixels. */
export const STAGE_SCALE = 2;
/** Frame where the prompt shot hard-cuts to the reply shot. */
export const CUT = 110;

// ---------------------------------------------------------------------------------------------------------------
// props

export type PromptReplyColors = {
  /** the page */
  background: string;
  /** the prompt box */
  surface: string;
  /** primary text and the white of the icon tiles */
  ink: string;
  /** typed characters start in this tint and fade to `ink` */
  tint: string;
  /** the icon tile's colour while an activity is running */
  active: string;
  /** dim labels (activity rows) */
  label: string;
  /** status line */
  status: string;
  /** chip text, table header, table text, link, action icons */
  chipText: string;
  head: string;
  cell: string;
  link: string;
  icons: string;
  /** the table's "value" chip text */
  value: string;
  /** hairlines: chip borders, the connector between activities */
  line: string;
};

export type PromptReplyFonts = {
  /** Google Fonts family names, as `@remotion/google-fonts/<Family>` spells them */
  ui: string;
  mono: string;
  serif: string;
};

export type PromptReplyProps = {
  /** the name in the small chip under the reply */
  brand: string;
  /** what the user types */
  prompt: string;
  /** the two activity rows that tick in above the reply */
  activities: [string, string];
  /** the small line under the second activity */
  status: string;
  /** the reply, in the serif */
  reply: string;
  /** the table: three column heads and one row; the middle cell is plain, the last one a link */
  table: { head: [string, string, string]; row: [string, string, string] };
  fonts: PromptReplyFonts;
  colors: PromptReplyColors;
};

export const defaultProps: PromptReplyProps = {
  brand: 'Kinetograph',
  prompt: 'Can you turn this release into a video?',
  activities: ['Plan the cut', 'Render preview'],
  status: 'Cut the video and pulled its preview link.',
  reply: 'I’ve cut a 20-second launch video from this release’s changelog.  Link below:',
  table: {
    head: ['Video', 'Scenes', 'Link'],
    row: ['Launch • 0:20', 'Hero, changelog, pricing', 'Open in editor'],
  },
  fonts: { ui: 'Inter', mono: 'SourceCodePro', serif: 'CormorantGaramond' },
  colors: {
    background: '#1b1b1b',
    surface: '#373735',
    ink: '#ffffff',
    tint: '#d0a2a5',
    active: '#d5523e',
    label: '#737373',
    status: '#b4b4b4',
    chipText: '#b9b9b9',
    head: '#b6b6b6',
    cell: '#9e9e9e',
    link: '#b0b0b0',
    icons: '#d2d2d2',
    value: '#bd8d9b',
    line: '#3c3c3c',
  },
};

// ---------------------------------------------------------------------------------------------------------------
// fonts

export interface Faces {
  ui: string;
  mono: string;
  serif: string;
}

/** Loads the three families (Google Fonts, downloaded once into the cache) and returns the names to use. */
export function loadFaces(fonts: PromptReplyFonts): Faces {
  const load = (family: string, weights: string[]) =>
    makeGoogleFont(family).loadFont('normal', { weights }).fontFamily;
  return {
    ui: load(fonts.ui, ['400', '500']),
    mono: load(fonts.mono, ['400']),
    serif: load(fonts.serif, ['400', '500', '600']),
  };
}

/** line-height / size of the default fonts, to centre a text box on a point */
export const LH = { ui: 1.21, mono: 1.3, serif: 1.211 };

/** Letter-spacing, in px, of the reference's interface type at `size` px (Inter's own size-dependent tracking: tight
 *  in large type, a little open in small). The text element has no letter-spacing, so callers offset each character. */
export const tracking = (size: number) => (-0.0223 + 0.185 * Math.exp(-0.1745 * (size / 2))) * size;

// ---------------------------------------------------------------------------------------------------------------
// timing

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
export const easeOutCubic = Easing.bezier(0.215, 0.61, 0.355, 1);
export const easeOutQuad = Easing.bezier(0.25, 0.46, 0.45, 0.94);
export const easeInOut = Easing.bezier(0.45, 0, 0.55, 1);

/** 0..1 over [from, from + dur] with an easing, held outside */
export const ramp = (f: number, from: number, dur: number, easing: (t: number) => number = (t) => t) =>
  interpolate(f, [from, from + dur], [0, 1], { ...clamp, easing });

/** A monotone cubic through [frame, value] keys: a camera that glides through measured marks without overshoot. */
export function glide(f: number, k: [number, number][]): number {
  const n = k.length;
  if (f <= k[0][0]) return k[0][1];
  if (f >= k[n - 1][0]) return k[n - 1][1];
  const d = k.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const s0 = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const s1 = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return s0 * s1 <= 0 ? 0 : (2 * s0 * s1) / (s0 + s1);
  });
  let i = 0;
  while (f > k[i + 1][0]) i++;
  const h = k[i + 1][0] - k[i][0];
  const t = (f - k[i][0]) / h;
  const t2 = t * t;
  const t3 = t2 * t;
  return (
    (2 * t3 - 3 * t2 + 1) * k[i][1] +
    (t3 - 2 * t2 + t) * h * d[i] +
    (-2 * t3 + 3 * t2) * k[i + 1][1] +
    (t3 - t2) * h * d[i + 1]
  );
}

/** colour a -> b, t 0..1 */
export const mix = (a: string, b: string, t: number) => interpolateColors(Math.min(1, Math.max(0, t)), [0, 1], [a, b]);

/** Kinetograph blends in linear light, a browser in sRGB. A fade drawn at `alpha` here would look brighter than the same
 *  fade in the reference, so this returns the opacity that gives the sRGB result: the colour `fg` fading in over `bg`
 *  (#rgb or #rrggbb). Anything else is returned unchanged. */
export function fadeAlpha(alpha: number, fg: string, bg: string): number {
  const parse = (c: string): number[] | null => {
    const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(c.trim());
    if (!m) return null;
    const h = m[1].length === 3 ? m[1].split('').map((x) => x + x).join('') : m[1];
    return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);
  };
  const lin = (v: number) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const a = parse(fg);
  const b = parse(bg);
  if (!a || !b) return alpha;
  const lum = (c: number[]) => 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]);
  const lf = lum(a);
  const lb = lum(b);
  if (Math.abs(lf - lb) < 1e-4) return alpha;
  // perceived (sRGB) level of the faded colour, taken on luminance, then back to the linear mix that reaches it
  const sv = (l: number) => (l <= 0.0031308 ? l * 12.92 : 1.055 * l ** (1 / 2.4) - 0.055);
  const target = sv(lb) + alpha * (sv(lf) - sv(lb));
  return Math.min(1, Math.max(0, (lin(target) - lb) / (lf - lb)));
}

// ---------------------------------------------------------------------------------------------------------------
// drawing helpers

/** A stroke with caps and joins (the TS type only names colour and width; the engine draws the rest). */
export const line = (s: { color: string; width: number; cap?: 'round' | 'butt'; join?: 'round' | 'miter' }): Stroke =>
  s as unknown as Stroke;

export const ICON = {
  copy: 'M9 9H20A1.5 1.5 0 0 1 21.5 10.5V20A1.5 1.5 0 0 1 20 21.5H10.5A1.5 1.5 0 0 1 9 20ZM5.5 15H4.5A1.5 1.5 0 0 1 3 13.5V4.5A1.5 1.5 0 0 1 4.5 3H13.5A1.5 1.5 0 0 1 15 4.5V5.5',
  speaker:
    'M2.6 9.2H5.6L11.8 4V20L5.6 14.8H2.6Z M15.6 7.4Q20.6 12 15.6 16.6 M18.4 5Q26.6 12 18.4 19',
  up: 'M7.2 10.5V21H3.8A1 1 0 0 1 2.8 20V11.5A1 1 0 0 1 3.8 10.5ZM7.2 10.5L11.3 3.4A2.2 2.2 0 0 1 14 5.4L13.4 9.5H19.4A2 2 0 0 1 21.3 12.2L19.6 19.4A2.2 2.2 0 0 1 17.5 21H7.2',
  down: 'M16.8 13.5V3H20.2A1 1 0 0 1 21.2 4V12.5A1 1 0 0 1 20.2 13.5ZM16.8 13.5L12.7 20.6A2.2 2.2 0 0 1 10 18.6L10.6 14.5H4.6A2 2 0 0 1 2.7 11.8L4.4 4.6A2.2 2.2 0 0 1 6.5 3H16.8',
  dots: 'M5.4 12h.01M12 12h.01M18.6 12h.01',
  plus: 'M12 3V21M3 12H21',
};

export const Icon: React.FC<{
  id: string;
  d: string;
  size: number;
  color: string;
  stroke?: number;
  x: number;
  y: number;
  opacity?: number;
}> = ({ id, d, size, color, stroke = 1.7, x, y, opacity = 1 }) => (
  <Layer id={id} x={x} y={y} scale={size / 24} opacity={opacity}>
    <Path id={`${id}-p`} d={d} stroke={line({ color, width: stroke, cap: 'round', join: 'round' })} />
  </Layer>
);

/** The small video-camera glyph in an activity tile, traced from the reference: an open box (a "C" with a 3 px stroke)
 *  and a lens that widens to the right. Coordinates are the row's own (tile top-left at 61.7, 0.6, 33.4 square). */
export const CameraGlyph: React.FC<{ id: string; color: string }> = ({ id, color }) => (
  <Layer id={id}>
    <Path
      id={`${id}-body`}
      d="M81.5 11H72.4A1.5 1.5 0 0 0 70.9 12.5V20.95A1.5 1.5 0 0 0 72.4 22.45H81.5"
      stroke={line({ color, width: 3, cap: 'butt', join: 'round' })}
    />
    <Path
      id={`${id}-lens`}
      d="M82.1 14.4L86.7 12.1V21.6L82.1 19.9Z"
      fill={color}
      stroke={line({ color, width: 0.9, join: 'round' })}
    />
  </Layer>
);

// Shot 1 (frames 0-109): the prompt box. Characters type in at an uneven pace, each in a warm tint that fades to white
// as it ages; the box drifts left and settles, then a pink hairline pulses round it as the prompt sends.

import React from 'react';
import { Layer, Path, Rect, Text } from '@kinetographdev/core';
import { measureText } from '@remotion/layout-utils';
import { CUT, easeOutCubic, glide, line, mix, ramp, tracking } from './lib.js';
import type { Faces, PromptReplyProps } from './lib.js';

/** Frame each character of the default 39-character prompt appears (measured from the reference). Negative: the first
 *  characters are already there at frame 0. Other prompt lengths resample this curve, so the pace stays uneven. */
const TYPE_AT = [
  -4, -3, -2, -1, 0, 2, 4, 6, 7, 9, 10, 12, 13, 15, 16, 18, 20, 21, 22, 24, 26, 28, 30, 31, 33, 34, 36, 38, 40, 42, 44,
  46, 48, 50, 53, 55, 58, 62, 70,
];

export function typeTimes(count: number): number[] {
  if (count <= 1) return [0];
  const last = TYPE_AT.length - 1;
  return Array.from({ length: count }, (_, i) => {
    const u = (i / (count - 1)) * last;
    const a = Math.floor(u);
    const b = Math.min(last, a + 1);
    return TYPE_AT[a] + (TYPE_AT[b] - TYPE_AT[a]) * (u - a);
  });
}

// camera: where the box's top-left corner is on screen (reference pixels)
const BOX_X: [number, number][] = [
  [0, 74], [35, 74], [45, 70], [55, 59], [60, 51], [65, 45], [70, 41], [75, 39], [80, 38], [90, 37],
];
const BOX_Y: [number, number][] = [
  [0, 153], [5, 144], [10, 140], [15, 137], [20, 135], [25, 134], [30, 133], [35, 131], [50, 130], [95, 130],
  [100, 128], [102, 127], [104, 126], [106, 123], [108, 119], [110, 115],
];

const BOX_H = 280;
const BOX_W = 1400; // runs off the right edge of the frame
const PAD_X = 55.75;
const TEXT_SIZE = 48.3;
/** the widest a prompt may run before its type shrinks to fit (the reference's own line is 836 px at 48) */
const MAX_LINE = 840;

export const PromptShot: React.FC<{ f: number; props: PromptReplyProps; faces: Faces }> = ({ f, props, faces }) => {
  const { colors, prompt } = props;
  const bx = glide(f, BOX_X);
  const by = glide(f, BOX_Y);
  const chars = Array.from(prompt);
  const times = typeTimes(chars.length);
  const typed = times.filter((t) => t <= f).length;
  // light type blends heavier here (linear light) than in the reference; a touch less white evens the strokes out
  const textInk = mix(colors.ink, colors.surface, 0.075);
  const tx = bx + PAD_X;
  const ty = by + 50;

  // caret sits after the last typed character; measured as the advance of "prefix + x" minus "x" so a trailing space counts
  const natural = measureText({ text: prompt, fontFamily: faces.ui, fontSize: TEXT_SIZE }).width + chars.length * tracking(TEXT_SIZE);
  const size = natural > MAX_LINE ? (TEXT_SIZE * MAX_LINE) / natural : TEXT_SIZE;
  const k = size / TEXT_SIZE;
  const ls = tracking(size) + 0.015 * k;
  const w = (text: string) => measureText({ text, fontFamily: faces.ui, fontSize: size }).width;
  const adv = (s: string) => w(s + '|') - w('|') + Array.from(s).length * ls;
  const caretX = tx + (typed > 0 ? adv(chars.slice(0, typed).join('')) : 0) + 4.8;
  const caretOn = f < 101;

  // the send highlight: a pink hairline that swells in and fades out again
  const ring = ramp(f, 86, 9, easeOutCubic) * (1 - ramp(f, 97, 11));
  const ringColor = mix(colors.surface, '#e8969f', 0.36);

  return (
    <Layer id="prompt-shot">
      <Layer id="box" x={bx} y={by}>
        <Rect id="box-fill" width={BOX_W} height={BOX_H} radius={26} fill={colors.surface} />
        <Layer id="box-ring" opacity={ring}>
          <Rect id="box-ring-line" width={BOX_W} height={BOX_H} radius={26} stroke={line({ color: ringColor, width: 1.5 })} />
        </Layer>
        <Layer id="plus" x={99.5 - 20} y={204.5 - 20}>
          <Path id="plus-h" d="M0 20H40" stroke={line({ color: colors.ink, width: 3, cap: 'butt' })} />
          <Path id="plus-v" d="M20 0V40" stroke={line({ color: colors.ink, width: 3, cap: 'butt' })} />
        </Layer>
      </Layer>
      <Layer id="typed" x={tx} y={ty}>
        <Text
          id="typed-text"
          font={faces.ui}
          size={size}
          weight={400}
          color={textInk}
          chars={(_ch, i) => {
            const age = f - times[i];
            if (age < 0) return { x: i * ls, opacity: 0 };
            return { x: i * ls, color: mix(colors.tint, textInk, (age - 8) / 36) };
          }}
        >
          {prompt}
        </Text>
      </Layer>
      {caretOn ? (
        <Rect id="caret" x={caretX} y={by + 82.25 - 21.25 * k} width={3} height={42.5 * k} fill={mix(colors.tint, colors.ink, 0.4)} />
      ) : null}
    </Layer>
  );
};

export const PROMPT_END = CUT;

// Shot 2 (frames 110-299): the agent reply. Everything sits on one tall page that a camera scrolls up through; the
// activity rows tick in, then the status line, the serif reply, the brand chip, the table and the action icons fade up
// one after another. Positions are the settled page's (reference pixels); the camera adds its offset.

import React from 'react';
import { Layer, Rect, Text } from '@kinetographdev/core';
import { measureText } from '@remotion/layout-utils';
import { CameraGlyph, ICON, Icon, easeOutCubic, easeOutQuad, fadeAlpha, glide, line, mix, ramp, tracking } from './lib.js';
import type { Faces, PromptReplyProps } from './lib.js';

// camera offsets while the page scrolls up and left to its rest position (measured frame by frame)
const CAM_Y: [number, number][] = [
  [110, 179], [112, 162], [114, 146], [116, 135], [118, 124], [120, 114], [122, 99], [124, 86], [126, 74], [128, 66],
  [130, 59], [132, 53], [134, 46], [136, 39], [138, 33], [140, 28], [142, 24], [144, 23], [146, 21], [148, 19],
  [150, 17], [152, 14], [154, 13], [156, 11], [158, 9], [160, 8], [164, 6], [168, 5], [170, 4], [174, 3], [180, 2],
  [184, 1], [194, 0],
];
const CAM_X: [number, number][] = [
  [110, 24], [112, 23], [114, 20], [116, 18], [118, 15], [120, 12], [122, 11], [124, 10], [130, 7], [135, 5], [140, 3],
  [145, 2], [150, 1], [165, 0],
];

// when each piece arrives (frame, duration)
const T = {
  planStart: 110,
  renderStart: 122,
  status: [130.5, 18],
  reply: [139.5, 15],
  chip: [153.5, 12],
  head: [166, 26],
  cell: [[188.5, 12], [199.5, 11], [207.5, 11]],
  icons: [221.2, 17.5],
} as const;

const LEFT = 61;
const COLS = [62, 464, 758];

/** a text box placed by where the top of its ink should land */
const Put: React.FC<{
  id: string;
  x: number;
  inkTop: number;
  size: number;
  font: string;
  weight?: number;
  color: string;
  opacity?: number;
  lift: number; // how far the ink top sits below the text box's top, in em
  track?: boolean; // apply the reference's interface-type letter-spacing
  children: string;
}> = ({ id, x, inkTop, size, font, weight = 400, color, opacity = 1, lift, track, children }) => (
  <Layer id={id} x={x} y={inkTop - lift * size} opacity={opacity}>
    <Text id={`${id}-t`} font={font} size={size} weight={weight} color={color} chars={track ? (_c, i) => ({ x: i * tracking(size) }) : undefined}>
      {children}
    </Text>
  </Layer>
);

const ActivityRow: React.FC<{
  id: string;
  y: number;
  text: string;
  start: number;
  f: number;
  faces: Faces;
  props: PromptReplyProps;
  size: number;
  opacity?: number;
}> = ({ id, y, text, start, f, faces, props, size, opacity = 1 }) => {
  const { colors } = props;
  // the tile starts in the active colour and settles to white over ten frames
  const t = ramp(f, start, 10);
  return (
    <Layer id={id} y={y} opacity={opacity}>
      <Rect id={`${id}-tile`} x={61.7} y={0.6} width={33.4} height={33.4} radius={8} fill={mix(colors.active, colors.ink, t)} />
      <CameraGlyph id={`${id}-cam`} color="#1b1b1b" />
      <Put id={`${id}-label`} x={LEFT + 51.2} inkTop={11.6} size={size} font={faces.ui} color={colors.label} lift={0.3} track>
        {text}
      </Put>
    </Layer>
  );
};

export const ReplyShot: React.FC<{ f: number; props: PromptReplyProps; faces: Faces }> = ({ f, props, faces }) => {
  const { colors, table } = props;
  const camX = glide(f, CAM_X);
  const camY = glide(f, CAM_Y);
  // rows the camera has scrolled clean off the top are not drawn at all
  const offscreen = (y: number, h = 34) => y + h + camY < 0;

  // fades are timed on the reference's (sRGB) look; fadeAlpha converts each to the opacity that gives it here
  const fa = (a: number, color: string) => fadeAlpha(a, color, colors.background);
  const fade = (a: readonly [number, number], e = easeOutQuad) => ramp(f, a[0], a[1], e);
  const status = fa(fade(T.status, easeOutCubic), colors.status);
  const reply = fa(fade(T.reply), colors.ink);
  const chip = fa(fade(T.chip, easeOutCubic), colors.chipText);
  const head = fa(ramp(f, T.head[0], T.head[1], (t) => t * t * (3 - 2 * t)), colors.head);
  const cells = [fa(fade(T.cell[0]), colors.value), fa(fade(T.cell[1]), colors.cell), fa(fade(T.cell[2]), colors.link)];
  const icons = fa(ramp(f, T.icons[0], T.icons[1]), colors.icons);

  const brandW = measureText({ text: props.brand, fontFamily: faces.ui, fontSize: 14.3 }).width + Array.from(props.brand).length * tracking(14.3);
  const valueW = measureText({ text: table.row[0], fontFamily: faces.mono, fontSize: 18.6 }).width;
  const linkW = measureText({ text: table.row[2], fontFamily: faces.serif, fontSize: 21.6, fontWeight: 400 }).width;

  return (
    <Layer id="reply-shot" x={camX} y={camY}>
      {offscreen(-87) ? null : (
        <ActivityRow id="act1" y={-87} text={props.activities[0]} start={T.planStart} size={19.5} f={f} faces={faces} props={props} />
      )}
      {f >= T.renderStart && !offscreen(-2) ? (
        <Layer id="act2-wrap">
          {offscreen(-45, 35) ? null : <Rect id="connector" x={77} y={-45} width={2} height={35} fill={colors.line} />}
          <ActivityRow id="act2" y={-2} text={props.activities[1]} start={T.renderStart} size={20.5} f={f} faces={faces} props={props} />
        </Layer>
      ) : null}

      <Put id="status" x={62.2} inkTop={108.3} size={17.9} font={faces.ui} color={colors.status} opacity={status} lift={0.27} track>
        {props.status}
      </Put>
      <Put id="reply" x={61.3} inkTop={152.6} size={26.35} font={faces.serif} weight={600} color={colors.ink} opacity={reply} lift={0.2}>
        {props.reply}
      </Put>

      <Layer id="brand" opacity={chip}>
        <Rect
          id="brand-box"
          x={62.5}
          y={234.5}
          width={brandW + 32}
          height={26}
          radius={7}
          stroke={line({ color: colors.line, width: 1.3 })}
        />
        <Put id="brand-t" x={75.6} inkTop={243.4} size={14.3} font={faces.ui} color={colors.chipText} lift={0.27} track>
          {props.brand}
        </Put>
      </Layer>

      <Layer id="thead" opacity={head}>
        {table.head.map((h, i) => (
          <Put key={i} id={`th${i}`} x={COLS[i]} inkTop={295} size={24.6} font={faces.serif} weight={500} color={colors.head} lift={0.2}>
            {h}
          </Put>
        ))}
      </Layer>

      <Layer id="trow0" opacity={cells[0]}>
        <Rect id="value-box" x={62.5} y={332.5} width={valueW + 27} height={31} radius={6.5} stroke={line({ color: colors.line, width: 1.3 })} />
        <Put id="value-t" x={74.4} inkTop={338} size={18.6} font={faces.mono} color={colors.value} lift={0.27}>
          {table.row[0]}
        </Put>
      </Layer>
      <Put id="trow1" x={COLS[1] + 2} inkTop={342} size={20.7} font={faces.serif} weight={400} color={colors.cell} opacity={cells[1]} lift={0.2}>
        {table.row[1]}
      </Put>
      <Layer id="trow2" opacity={cells[2]}>
        <Put id="link-t" x={COLS[2]} inkTop={342} size={21.6} font={faces.serif} weight={400} color={colors.link} lift={0.2}>
          {table.row[2]}
        </Put>
        <Rect id="link-underline" x={COLS[2]} y={362} width={linkW} height={1.1} fill={colors.link} />
      </Layer>

      <Layer id="actions" opacity={icons}>
        {(['copy', 'speaker', 'up', 'down', 'dots'] as const).map((k, i) => (
          <Icon key={k} id={`ic-${k}`} d={ICON[k]} size={17} color={colors.icons} stroke={k === 'dots' ? 2.9 : 1.55} x={75 + i * 30 - 8.5 + (k === 'copy' ? 0.5 : 0)} y={398.5 - 8.5} />
        ))}
      </Layer>
    </Layer>
  );
};
